const refinedFixture = () => {
	const input = fixture(), declaration = input.metadata.modules[0].declarations[0];
	const abi = { cType: "lean_object*", box: "lean_box", unbox: "lean_unbox", heap: true };
	const nat = { kind: "primitive", name: "nat", lean: "Nat", abi };
	const checked = { kind: "refinement", base: nat
		, predicate: { kind: "subtype", constructor: "Sample.checked" }, abi };
	declaration.parameters.push({ name: "extra", binderInfo: "explicit"
		, typeExpression: "{ value : Nat // 0 < value }" });
	declaration.typeExpression = "Sample.Tree → { value : Nat // 0 < value } → Sample.Tree";
	declaration.projection.parameters.push({ name: "extra", type: checked });
	return input;
};

test("recursive graph refinement validators derive every carrier from the authenticated signature", () => {
	const input = refinedFixture();
	const outputs = [
		generateCompiledNativeLeanAdapters(createCompiledNativeModel(input
			, { nativeRefinements: true })).leanSource
		, generateCompiledPhpWasmLeanAdapters(createCompiledPhpWasmModel(input)).leanSource
	];
	for(const source of outputs)
	{
		assert.doesNotMatch(source, /\bundefined\b/u);
		assert.match(source, /def export0_refinement_1 \(carrier : _root_\.Array _root_\.Nat\) : _root_\.UInt8 :=/u);
		assert.match(source, /def export0 \(a0 : \(_root_\.Array _root_\.Sample\.Tree\)\) \(a1 : \(_root_\.Array _root_\.Nat\)\)/u);
		assert.match(source, /_root_\.Sample\.checked value/u);
	}

	const item = {
		symbol: "checked", wrapper: "checked"
		, parameters: [{ name: "value" }]
		, refinements: {
			parameters: [{ kind: "fin", bound: "3" }], result: null
		}
	};
	assert.throws(() => componentCarrierRefinementValidators(item, true)
		, /Refinement validator 0 has no carrier Lean type/u);
	assert.throws(() => componentCarrierRefinementValidators({ ...item
		, parameters: [{ leanType: "" }] }, true), /no carrier Lean type/u);
	assert.deepEqual(componentCarrierRefinementValidators(item, false), []);
});

const callableValidatorCarriers = source => {
	const wrappers = new Map();
	for(const match of source.matchAll(/^def (\w+) (\(a0 : .*) : .* :=$/gmu))
	{
		const groups = [];
		let depth = 0, start = 0;
		for(const [index, character] of [...match[2]].entries())
		{
			if(character === "(" && depth++ === 0) start = index;
			if(character === ")" && --depth === 0) groups.push(match[2].slice(start + 1, index));
		}
		wrappers.set(match[1], groups.map(group => /^a\d+ : \((_root_\.Array .*)\)$/u.exec(group)[1]));
	}
	return [...source.matchAll(/^def (\w+)_refinement_(\d+) \(carrier : (_root_\.Array .*)\) : _root_\.UInt8 :=$/gmu)]
		.filter(match => wrappers.has(match[1]))
		.map(match => ({ wrapper: match[1], index: Number(match[2])
			, carrier: match[3], expected: wrappers.get(match[1])[Number(match[2])] }));
};

test("reviewed PHP-Wasm Fin callbacks validate export arguments over their exact wrapper carriers", () => {
	const ir = reviewedCallbackFinReview({ hostReply: true });
	const copiedGraph = createNativeCallableGraphDescriptor(ir);
	const model = {
		schemaVersion: 5, profile: "php-wasm-copied-v1"
		, pointerBits: 32, byteOrder: "little"
		, component: ir.component, bindingIr: ir, copiedGraph
		, exports: ir.declarations.map(declaration => {
			const entry = copiedGraph.exports.find(item => item.bindingId === declaration.id);
			const refinements = declaration.source.extensions["lean-lang.org/refinements"];
			return {
				module: "ReviewedCallbacks", name: declaration.source.declaration
				, bindingId: declaration.id, symbol: `${entry.symbol}_lean`
				, parameters: declaration.parameters.map(parameter => ({ name: parameter.name }))
				, ...refinements ? { refinements } : {}
			};
		})
	};
	const source = generateCompiledPhpWasmLeanAdapters(model).leanSource;
	assert.doesNotMatch(source, /\bundefined\b/u);
	assert.match(source, /opaque recovery_[a-f0-9]+/u);
	assert.match(source, /opaque reject_[a-f0-9]+/u);
	const carriers = callableValidatorCarriers(source);
	assert.ok(carriers.length > 0);
	assert.ok(carriers.some(entry => entry.index === 1
		&& entry.carrier === "_root_.Array _root_.Nat"));
	for(const entry of carriers)
		assert.equal(entry.carrier, entry.expected
			, `${entry.wrapper}_refinement_${entry.index}`);
});
